using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.CharacterSums;

internal sealed class PascadiOriginalRetainedCountDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The original retained long-chart tuple count consumes actual record reconstruction and the physical bad-degree average under one structural seventh-height gap. The earlier numerical-cutoff statement remains a consequence with its original type, with no supplied endpoint family or counting bound.",
        H("An actual retained original-tuple bound"),
        Blocks(
            Paragraph(Text("Write K7=seventhHeightConstant=max(10368·3^9, max(14256, 24·(8·18)^4)).")),
            Describe.Lean(DescribeId.Create("actual-retained-long-original-tuple-count-seventh"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalRetainedCount.actual_retained_long_tuple_count_seventh"),
                H("Retained original tuples under seventh height"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every epsilon>0 there is C>0 chosen before prime p, the real widths and actual row set T. Assume 1<=X<=Y, 3Y<p^2, A=XY<2p^4, H>0 with H^2=A and H>=p, two alternating units modulo p^3, and the literal row boxes and original word equal to minus the identity. The original middle entries and endpoint first coordinates are units. For each occupied actual middle pair supply its reduced basis, require the long condition p^6<A*weightedSq(B.R), a unit B.R.1, and a unit original right side 1+a1*a2*t*w. The single gap K7*(32*(A/p^3))^7<p^5 then gives card(T)<=C*p^epsilon*(A+(A/p)*L+A^2/p^4)+sqrt(C*p^epsilon*A^6*L/p^15), with L=1+log(2p)/log 2. No M parameter or old eighth-height cutoff is assumed.")),
                    Paragraph(Text("The actual dyadic record reconstruction supplies all endpoint fibers and their exact tuple-cardinality sum. Apply actual_long_bad_degree_average_seventh to those same fibers, count the occupied parameters by 9XY, and insert that count into the original square-root moment term. This strengthens the numerical input while preserving the original physical and unit restrictions. The original reconstruction and averaging framework is retained; the structural seventh-height supplier is the new input."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-retained-long-original-tuple-count"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalRetainedCount.actual_retained_long_tuple_count"),
                H("Average the defect in the original six-word count"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For each epsilon>0 one C works for every prime p, positive H with H^2=XY and H>=p, widths 1<=X<=Y with 3Y<p^2 and XY<2p^4, and the stated numerical separation conditions. Fix the original alternating units. T consists of actual bounded six-return rows with word minus the identity, unit middle entries and unit endpoint first coordinates. Reduced bases are supplied only for actual middle pairs in T.image originalMiddle; they must be long and have unit first shortest-vector coordinate, and the original right side 1+a1*a2*t*w is a unit. Then, with A=XY and L=1+log(2p)/log 2, the actual count is at most C*p^epsilon*(A+(A/p)*L+A^2/p^4)+sqrt(C*p^epsilon*A^6*L/p^15).")),
                    Paragraph(Text("This preserves the original numerical-cutoff statement and its constant uniformity in M. For nonempty T, the actual long-chart geometry gives 1<=32A/p^3. seventh_height_gap_of_old_cutoffs derives the single seventh-height gap from the retained old cap and eighth-height cutoff, and actual_retained_long_tuple_count_seventh supplies the count. The empty set is handled directly. The original residual cutoff remains in the type for compatibility; no separate endpoint family or weight budget is supplied."))),
                DescribeRole.Theorem),
            Paragraph(Text("The compatibility statement retains (32A/p^3)^5<=M^5*p^3, (10368*3^9)^5*M^35<p^4 and (24*(8*18)^4)^5*M^40<p. The new seventh-height statement does not require those three assumptions. Absorbing the displayed moment and logarithms, adding the other actual charts and restoring all scalar centers remain separate arguments. The original six-letter problem and pencil are due to Pascadi; this module alone does not solve the arbitrary-modulus conjecture.")))));
}
